다음 C 함수에 대하여 F(L, 0, n-1)를 수행할 경우 시간 복잡도는?
    int F(int L[], int p, int q)
    {
        if (p<q)
        { int r, f1, f2;
            r = (p+q)/2;
            f1 = 2*F(L, p, r);
            f2 = 2*F(L, r+1, q);
            return f1+f2;
        }
        else if (p == q)
            return L[p]*L[p];
        else
            return 0;
    }

다음 재귀(recursion) 함수는 이진트리의 루트(root)를 가리키는 포인터를 사용하여 특정한 작업을 수행한다. 구체적으로 어떤 작업을 수행하는가?
    typedef struct node_struct {
        int data;
        struct node_struct *left, *right;
    } node_t;
    void JOB_Tree(node_t *root) {
        node_t *temp;
        if (root == NULL) return;
        temp = root->right;
        root->right = root->left; root->left = temp;
        JOB_Tree(root->left); JOB_Tree(root->right);
    }

