int queue[MAX_QUEUE_SIZE];
int front, rear;
void enqueue(int item) {
    if( (rear + 1) % MAX_QUEUE_SIZE == front ) {
        printf("queue is full\n");
        return;
    }
    rear = (rear + 1) % MAX_QUEUE_SIZE;
    queue[rear] = item;
}
int dequeue() {
    if( front == rear ) {
        printf("queue is empty\n");
        return -1;
    }
    front = (front + 1) % MAX_QUEUE_SIZE;
    return queue[front];
}

