    int binarySearch(int *a, int key, int low,
                            int high)
    {
        int middle;
        while (low <= high) {
            middle = (low + high) / 2;
            if (key == a[middle])
                return middle;
            else if (key > a[middle])
                low = middle + 1;
            else
                high = middle - 1;
        }
        return -1;
    }

