    #include <stdio.h>
    typedef struct stack {
        int data[10]; int top;
    } stack;
    stack s1, s2;

    void push(stack *ss, int i) {
        ss->top = ss->top + 1;
        ss->data[ss->top] = i;
    }

    int pop(stack *ss) {
        return ss->data[ss->top--];
    }

    int size(stack *ss) {
        return ((ss->top) + 1);
    }

    void push2(int n) {
        push(&s1, n);
    }

    int pop2() {
        if(size(&s2) == 0) {
            int s = size(&s1);
            for(int i = 0; i < s; i++)
                push(&s2, pop(&s1));
        }
        return pop(&s2);
    }

    int main(int argc, char **argv) {
        s1.top = s2.top = -1;
        push2(1); push2(2); push2(3);
