    int heapify(int *a, int n) {
        int item = a[1], temp = a[n];
        int i = 1, j = 2;

        a[n] = 0, n = n-1;
        while ( j <= n ) {
            if ( j < n && a[j] > a[j + 1] ) j++;
            if ( temp < a[j] ) break;
            else {
                a[i] = a[j];
                i = j;
                j = j*2;
            }
        }
        a[i] = temp;
        return item;
    }

