    #define SWAP(x, y, t) ( (t)=(x), (x)=(y), (y)=(t) )

    void heap_sort(int L[], int n){
        int i, temp;
        for(i = n/2; i >= 1; i--) ······ (가)
            adjust(L, i, n);
        for(i = n-1; i >= 1; i--) { ······ (나)
