    void adjust(int L[], int root, int n) {
        int next = 2 * root;
        int X = L[root];
        while(next <= n) {
            if(next < n && L[next] < L[next + 1])
                next++;
            if(X > L[next]) break;
            L[next / 2] = L[next];
            next *= 2;
        }
        L[next / 2] = X;
    }
