    class Node:
        def __init__(self, data, next):
            self.data = data
            self.next = next
    class SinglyLinkedList:
        def __init__(self):
            self.head = None
        def func1(self, data):
            node = self.head
            self.head = Node(data, node)
        def func2(self, data):
            if self.head is None: self.func1(data)
            else :
                node = self.head
                while node.next is not None: node = node.next
                node.next = Node(data, None)
        def func3(self, pos):
            if pos < 0: return None
            node = self.head
            while pos > 0 and node != None:
                node = node.next
                pos -= 1
            return node
        def showList(self):
            node = self.head
            while node :
                print(node.data, end=' ')
                node = node.next

