    #define SWAP(x,y) {int temp = x; x = y; y = temp;}

    int splitArray(int arr[], int low, int high) {
        int pi = (low + high)/2;
        SWAP(arr[pi], arr[high]);
        int pivot = arr[high];

        int i = low - 1;
        for(int j = low; j < high; j++) {
            if(arr[j] < pivot) {
                i++;
                SWAP(arr[i], arr[j]);
            }
        }
        SWAP(arr[high], arr[i + 1]);
        return i + 1;
    }

    void arraySort(int arr[], int low, int high) {
        if(low < high) {
            int pi = splitArray(arr, low, high);
            arraySort(arr, low, pi - 1);
            arraySort(arr, pi + 1, high);
        }
    }

