    #include <stdio.h>

    int count = 0;

    void new_hanoi(int n, char from, char tmp, char to) {
        if (n <= 2)
            count += n;
        else {
            new_hanoi(n - 2, from, to, tmp);
            count += 2;
            new_hanoi(n - 2, tmp, from, to);
        }
    }

    int main() {
        new_hanoi(9, 'A', 'B', 'C');
        printf("%d", count);
        return 0;
    }

