    public class SearchAlgorithm {
        private static int[] index_list;
        private static int size;
        private static void reset() {
            index_list = new int[1];
            size = 0;
        }
        private static void resize(int newsize) {
            int[] nlist = new int[newsize];
            for(int i = 0; i < size; i++)
                nlist[i] = index_list[i];
            index_list = nlist;
        }
        private static void insert_index(int index) {
            if(size == index_list.length) resize(2 * size);
            index_list[ (가) ] = index;
        }
        public static int[] search(int[] data, int key) {
            (나) ;
            for(int i = 0; i < data.length; i++)
                if(data[i] == key) insert_index(i);
            int[] result_list = new int[size];
            for(int i = 0; i < result_list.length; i++)
                result_list[i] = index_list[i];
            return result_list;
        }
        public static void main(String[] args) {
            int[] data = {12, 45, 23, 43, 23, 54, 12, 23};
            int[] keys = {12, 13, 23, 43};
            String index_f = "(";
            for(int i = 0; i < keys.length; i++) {
                int key = keys[i];
                int[] indexs = search(data, key);
                index_f += key + ":" + indexs.length;
                if(i != keys.length - 1) index_f += ",";
            }
            System.out.println(index_f + ")");
            return;
        }
    }
