다음 Java 코드에 적용된 디자인 패턴과 Student 클래스와 MemberGenerator 클래스 간 관계를 옳게 짝 지은 것은?
interface Member{ void printType(); }

class Student implements Member {
    public void printType()
        { System.out.println("Student"); }
}

class Staff implements Member {
    public void printType()
        { System.out.println("Staff"); }
}

class Professor implements Member {
    public void printType()
        { System.out.println("Professor"); }
}

class MemberGenerator {
    public Member newMember(String memberType){
        if(memberType.equals("Student"))
            return new Student();
        else if(memberType.equals("Staff"))
            return new Staff();
        else if(memberType.equals("Professor"))
            return new Professor();
        return null;
    }
}

