다음 제시된 Java 코드에 포함된 코드 스멜과 이를 해결하기 위한 리팩토링 기법에 대한 설명으로 옳지 않은 것은?
public class Employee {
    public static final int EMP1 = 0;
    public static final int EMP2 = 1;
    public static final int EMP3 = 2;
    private int empType;

    public Employee(int empType) {
        this.empType = empType;
    }

    public int paySalary() {
        switch (empType) {
            case EMP1:
                return 5000;
            case EMP2:
                return 6000;
            case EMP3:
                return 9000;
            default:
                throw new IllegalArgumentException(
                    "Invalid employee type");
        }
    }
}
